//! Cargo-driven `dxdiag.exe` link, generated by tools/cargo_cell_gen.py
//! from the cmake link it replaces.
//! The body is dxdiag-rust; reactos-link builds the PE.

use reactos_link::{Linker, ModuleKind, MsvcrtexKind};
use std::env;

fn main() {
    let arch = env::var("CARGO_CFG_TARGET_ARCH").expect("CARGO_CFG_TARGET_ARCH");
    let (target_json, entry) = match arch.as_str() {
        "x86" => ("i686-kernel.json", "_wWinMainCRTStartup"),
        "x86_64" => ("x86_64-pc-windows-gnu", "wWinMainCRTStartup"),
        "aarch64" => ("aarch64-pc-windows-gnullvm", "wWinMainCRTStartup"),
        o => panic!("dxdiag-cargo: unsupported arch {o}"),
    };

    let static_libs: &[&str] = match arch.as_str() {
        "x86" => &["sdk/lib/dxguid/libdxguid.a", "sdk/lib/udmihelp/libudmihelp.a", "sdk/lib/dmilib/libdmilib.a", "sdk/lib/crt/CMakeFiles/oldnames.dir/oldnames.a"],
        "x86_64" => &["sdk/lib/dxguid/libdxguid.a", "sdk/lib/udmihelp/libudmihelp.a", "sdk/lib/dmilib/libdmilib.a", "sdk/lib/crt/CMakeFiles/oldnames.dir/oldnames.a"],
        "aarch64" => &["sdk/lib/dxguid/libdxguid.a", "sdk/lib/udmihelp/libudmihelp.a", "sdk/lib/dmilib/libdmilib.a", "sdk/lib/crt/CMakeFiles/oldnames.dir/oldnames.a"],
        _ => unreachable!(),
    };

    Linker::new(target_json)
        .rust_staticlib("dxdiag-rust")
        .resource_from_rc("base/applications/dxdiag/dxdiag.rc", "dxdiag_res")
        .import_lib("win32ss/user/user32/user32.spec", "user32.dll", "user32")
        .import_lib("dll/win32/advapi32/advapi32.spec", "advapi32.dll", "advapi32")
        .import_lib("dll/win32/comctl32/comctl32.spec", "comctl32.dll", "comctl32")
        .import_lib("dll/directx/wine/dinput8/dinput8.spec", "dinput8.dll", "dinput8")
        .import_lib("dll/win32/setupapi/setupapi.spec", "setupapi.dll", "setupapi")
        .import_lib("dll/directx/dsound_new/dsound.spec", "dsound.dll", "dsound")
        .import_lib("dll/directx/ddraw/ddraw.spec", "ddraw.dll", "ddraw")
        .import_lib("dll/win32/version/version.spec", "version.dll", "version")
        .import_lib("win32ss/gdi/gdi32/gdi32.spec", "gdi32.dll", "gdi32")
        .import_lib("dll/win32/winmm/winmm.spec", "winmm.dll", "winmm")
        .import_lib("dll/directx/wine/d3d9/d3d9.spec", "d3d9.dll", "d3d9")
        .import_lib("dll/win32/msvcrt/msvcrt.spec", "msvcrt.dll", "msvcrt")
        .import_lib("dll/win32/kernel32/kernel32.spec", "kernel32.dll", "kernel32")
        .import_lib("dll/ntdll/def/ntdll.spec", "ntdll.dll", "ntdll")
        // cmake-built static libraries, reused until each has a cargo home.
        .static_libs(static_libs)
        .msvcrtex_crt(MsvcrtexKind::ExeWide)
        .link(ModuleKind::Win32Exe {
            entry: entry.into(),
            subsystem: "windows:5.01".into(),
        });
}
